package com.classicsneox.crossword.core
import kotlin.random.Random
object CrosswordWordBank{val words=listOf(WordEntry("MAHJONG","Juego chino de fichas que se emparejan"),WordEntry("SUDOKU","Cuadrícula lógica de números"),WordEntry("SOPA","Retícula donde se buscan palabras"),WordEntry("DOMINO","Fichas con puntos que se encadenan"),WordEntry("SOLITARIO","Juego de cartas para un jugador"),WordEntry("FICHA","Pieza de un juego"),WordEntry("TABLERO","Superficie donde se juega"),WordEntry("LETRA","Unidad de una palabra"),WordEntry("NUMERO","Cifra del sudoku"),WordEntry("CELDA","Casilla de una cuadrícula"),WordEntry("PUNTOS","Marcas del dominó"),WordEntry("NIVEL","Grado de dificultad"),WordEntry("TURNO","Momento de jugar"),WordEntry("JUEGO","Actividad con reglas"),WordEntry("CLASICO","Que nunca pasa de moda"))}
class CrosswordGenerator{private data class P(val e:WordEntry,val r:Int,val c:Int,val d:Direction){fun at(i:Int)=CellPosition(r+d.dr*i,c+d.dc*i)}
fun generate(difficulty:Difficulty,seed:Long):CrosswordPuzzle{val target=CrosswordWordBank.words.take(difficulty.wordCount);var best:List<P> = emptyList();val rnd=Random(seed);repeat(50){val order=target.shuffled(rnd).sortedByDescending{it.word.length};val grid=mutableMapOf<CellPosition,Char>();val placed=mutableListOf<P>();val first=order.first();first.word.forEachIndexed{i,ch->grid[CellPosition(0,i)]=ch};placed+=P(first,0,0,Direction.ACROSS);for(e in order.drop(1)){val cs=mutableListOf<P>();for(p in placed)for(i in p.e.word.indices)for(j in e.word.indices)if(p.e.word[i]==e.word[j]){val d=p.d.perpendicular;val r=p.at(i).row-d.dr*j;val c=p.at(i).col-d.dc*j;if(valid(grid,e.word,r,c,d,difficulty.maxSize))cs+=P(e,r,c,d)};if(cs.isNotEmpty()){val q=cs.maxByOrNull{intersections(grid,it)}!!;q.e.word.forEachIndexed{i,ch->grid[q.at(i)]=ch};placed+=q}};if(placed.size>best.size)best=placed;if(best.size==target.size)return@repeat};check(best.size==target.size){"No se pudo generar el crucigrama"};val minR=best.minOf{it.r};val minC=best.minOf{it.c};val maxR=best.maxOf{it.r+(it.e.word.length-1)*it.d.dr};val maxC=best.maxOf{it.c+(it.e.word.length-1)*it.d.dc};val h=maxR-minR+1;val w=maxC-minC+1;val grid=List(h){MutableList<Char?>(w){null}};val words=best.map{p->p.e.word.forEachIndexed{i,ch->grid[p.r-minR+p.d.dr*i][p.c-minC+p.d.dc*i]=ch};PlacedWord(p.e,p.r-minR,p.c-minC,p.d)};return CrosswordPuzzle(w,h,words,grid.map{it.toList()},seed,difficulty)}
private fun intersections(g:Map<CellPosition,Char>,p:P)=p.e.word.indices.count{g[p.at(it)]==p.e.word[it]}
private fun valid(g:Map<CellPosition,Char>,word:String,r:Int,c:Int,d:Direction,max:Int):Boolean{val cells=word.indices.map{CellPosition(r+d.dr*it,c+d.dc*it)};val minR=minOf(cells.minOf{it.row},g.keys.minOf{it.row});val maxR=maxOf(cells.maxOf{it.row},g.keys.maxOf{it.row});val minC=minOf(cells.minOf{it.col},g.keys.minOf{it.col});val maxC=maxOf(cells.maxOf{it.col},g.keys.maxOf{it.col});if(maxR-minR+1>max||maxC-minC+1>max)return false;for(i in word.indices){val p=cells[i];val old=g[p];if(old!=null&&old!=word[i])return false;if(old==null){val sr=d.dc;val sc=d.dr;if(g.containsKey(CellPosition(p.row+sr,p.col+sc))||g.containsKey(CellPosition(p.row-sr,p.col-sc)))return false}};return !g.containsKey(CellPosition(r-d.dr,c-d.dc))&&!g.containsKey(CellPosition(r+d.dr*word.length,c+d.dc*word.length))}}
